insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals) values ('improved_sanitation', '{"en": "Population living in households that use an improved sanitation facility", "hi": "बेहतर स्वच्छता सुविधा वाले परिवारों में रहने वाली आबादी"}'::jsonb, '{"en": "Improved sanitation", "hi": "बेहतर स्वच्छता"}'::jsonb, '{"en": "Share of people (all ages) whose household uses an improved toilet facility, as defined in the NFHS fact sheets. Survey estimate, not an administrative count.", "hi": "उन लोगों (सभी आयु) का प्रतिशत जिनका परिवार NFHS की परिभाषा के अनुसार बेहतर शौचालय सुविधा का उपयोग करता है। यह सर्वेक्षण अनुमान है, प्रशासनिक गिनती नहीं।"}'::jsonb, '%', 'multiple', true, null, 1, '[0, 100]'::jsonb, 1) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals) values ('electricity', '{"en": "Population living in households with electricity", "hi": "बिजली वाले परिवारों में रहने वाली आबादी"}'::jsonb, '{"en": "Electricity", "hi": "बिजली"}'::jsonb, '{"en": "Share of people (all ages) living in households that have an electricity connection. Says nothing about hours of supply.", "hi": "बिजली कनेक्शन वाले परिवारों में रहने वाले लोगों (सभी आयु) का प्रतिशत। इससे आपूर्ति के घंटों का पता नहीं चलता।"}'::jsonb, '%', 'multiple', true, null, 2, '[0, 100]'::jsonb, 1) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals) values ('clean_fuel', '{"en": "Households using clean fuel for cooking", "hi": "खाना पकाने के लिए स्वच्छ ईंधन का उपयोग करने वाले परिवार"}'::jsonb, '{"en": "Clean cooking fuel", "hi": "स्वच्छ रसोई ईंधन"}'::jsonb, '{"en": "Share of households whose main cooking fuel is clean (electricity, LPG/natural gas, biogas). This is use, not just an LPG connection, so it is lower than Ujjwala connection counts.", "hi": "उन परिवारों का प्रतिशत जिनका मुख्य रसोई ईंधन स्वच्छ है (बिजली, एलपीजी/प्राकृतिक गैस, बायोगैस)। यह वास्तविक उपयोग है, केवल एलपीजी कनेक्शन नहीं, इसलिए यह उज्ज्वला कनेक्शन संख्या से कम है।"}'::jsonb, '%', 'multiple', true, null, 3, '[0, 100]'::jsonb, 1) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals) values ('improved_water', '{"en": "Population living in households with an improved drinking-water source", "hi": "बेहतर पेयजल स्रोत वाले परिवारों में रहने वाली आबादी"}'::jsonb, '{"en": "Improved drinking water", "hi": "बेहतर पेयजल स्रोत"}'::jsonb, '{"en": "Includes piped water, public taps, tube wells and protected wells. It is not the same as a household tap connection (Jal Jeevan Mission), which will be added separately.", "hi": "इसमें पाइप से पानी, सार्वजनिक नल, ट्यूबवेल और सुरक्षित कुएँ शामिल हैं। यह घरेलू नल कनेक्शन (जल जीवन मिशन) के समान नहीं है, जिसे अलग से जोड़ा जाएगा।"}'::jsonb, '%', 'multiple', true, null, 4, '[0, 100]'::jsonb, 1) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals) values ('women_bank_account', '{"en": "Women age 15-49 having a bank or savings account that they themselves use", "hi": "15-49 वर्ष की महिलाएँ जिनके पास स्वयं उपयोग किया जाने वाला बैंक या बचत खाता है"}'::jsonb, '{"en": "Women''s own bank account", "hi": "महिलाओं का अपना बैंक खाता"}'::jsonb, '{"en": "Share of women age 15-49 with a bank or savings account they use themselves. Covers women only, so it is not the same as Jan Dhan account totals.", "hi": "15-49 वर्ष की उन महिलाओं का प्रतिशत जिनके पास स्वयं उपयोग किया जाने वाला बैंक या बचत खाता है। यह केवल महिलाओं पर है, इसलिए जन धन खातों की कुल संख्या के समान नहीं है।"}'::jsonb, '%', 'multiple', true, null, 5, '[0, 100]'::jsonb, 1) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals) values ('literacy', '{"en": "Literacy rate", "hi": "साक्षरता दर"}'::jsonb, '{"en": "Literacy", "hi": "साक्षरता"}'::jsonb, '{"en": "Share of people who can read and write with understanding in any language. The Census age base changed over time (whole population before 1951, age 5+ in 1951-1971, age 7+ from 1981), marked as breaks. UNESCO''s line covers adults 15+.", "hi": "किसी भी भाषा में समझ के साथ पढ़-लिख सकने वाले लोगों का प्रतिशत। जनगणना का आयु आधार समय के साथ बदला (1951 से पहले पूरी आबादी, 1951-1971 में 5+ आयु, 1981 से 7+ आयु), जिसे विराम के रूप में दिखाया गया है। यूनेस्को की रेखा 15+ वयस्कों की है।"}'::jsonb, '%', 'multiple', true, null, 6, '[0, 100]'::jsonb, 1) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals) values ('life_expectancy', '{"en": "Life expectancy at birth", "hi": "जन्म के समय जीवन प्रत्याशा"}'::jsonb, '{"en": "Life expectancy", "hi": "जीवन प्रत्याशा"}'::jsonb, '{"en": "Average years a newborn would live if current death rates held. Census actuarial estimates cover ten-year periods; SRS life tables cover five-year periods; UN figures are annual model estimates.", "hi": "यदि वर्तमान मृत्यु दरें बनी रहें तो एक नवजात के औसत जीवन वर्ष। जनगणना बीमांकिक अनुमान दस-वर्षीय अवधि के हैं; SRS जीवन तालिकाएँ पाँच-वर्षीय अवधि की; संयुक्त राष्ट्र के आँकड़े वार्षिक मॉडल अनुमान हैं।"}'::jsonb, 'years', 'multiple', true, null, 7, '[20, 80]'::jsonb, 1) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals) values ('infant_mortality', '{"en": "Infant mortality rate", "hi": "शिशु मृत्यु दर"}'::jsonb, '{"en": "Infant mortality", "hi": "शिशु मृत्यु दर"}'::jsonb, '{"en": "Deaths before age one per 1,000 live births. Lower is better. SRS is India''s official series from 1971; pre-1947 registration undercounted deaths.", "hi": "प्रति 1,000 जीवित जन्मों पर एक वर्ष से पहले होने वाली मृत्यु। कम बेहतर है। SRS 1971 से भारत की आधिकारिक श्रृंखला है; 1947 से पहले के पंजीकरण में मृत्यु कम दर्ज होती थी।"}'::jsonb, 'per 1,000 live births', 'multiple', false, null, 8, '[0, 200]'::jsonb, 0) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals) values ('gdp_per_capita', '{"en": "GDP per person (2011 international dollars, PPP)", "hi": "प्रति व्यक्ति GDP (2011 अंतरराष्ट्रीय डॉलर, PPP)"}'::jsonb, '{"en": "GDP per person", "hi": "प्रति व्यक्ति GDP"}'::jsonb, '{"en": "Average income per person, adjusted for inflation and price levels so years can be compared (Maddison Project 2023). Before 1947 the figures are academic reconstructions: Broadberry, Custodis and Gupta (2015) for 1600-1871, Heston (1983) for 1870-1900, and Maddison (1985) for 1900-46. Treat them as estimates with wide uncertainty.", "hi": "प्रति व्यक्ति औसत आय, मुद्रास्फीति और मूल्य स्तर के लिए समायोजित ताकि वर्षों की तुलना हो सके (मैडिसन प्रोजेक्ट 2023)। 1947 से पहले के आँकड़े अकादमिक पुनर्निर्माण हैं: 1600-1871 के लिए ब्रॉडबेरी, कस्टोडिस और गुप्ता (2015), 1870-1900 के लिए हेस्टन (1983), और 1900-46 के लिए मैडिसन (1985)। इन्हें काफ़ी अनिश्चितता वाले अनुमान मानें।"}'::jsonb, '2011 int. $', 'multiple', true, null, 9, '[0, 10000]'::jsonb, 0) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals) values ('state_income_per_capita', '{"en": "Per capita Net State Domestic Product, constant 2011-12 prices", "hi": "प्रति व्यक्ति शुद्ध राज्य घरेलू उत्पाद, स्थिर 2011-12 मूल्य"}'::jsonb, '{"en": "State income per person", "hi": "प्रति व्यक्ति राज्य आय"}'::jsonb, '{"en": "Average income produced per person in a state, in rupees at 2011-12 prices. Compiled by state statistics bureaus; RBI Handbook of Statistics on Indian States.", "hi": "किसी राज्य में प्रति व्यक्ति उत्पन्न औसत आय, 2011-12 के मूल्यों पर रुपये में। राज्य सांख्यिकी ब्यूरो द्वारा संकलित; RBI भारतीय राज्यों पर सांख्यिकी पुस्तिका।"}'::jsonb, '₹ (2011-12 prices)', 'multiple', true, null, 10, '[0, 400000]'::jsonb, 0) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('wb-eg-elc-accs-zs', 'World Bank WDI, original provider: World Bank (Energy Progress Report / SE4ALL), from household surveys and models', 'Access to electricity (% of population)', 'https://data.worldbank.org/indicator/EG.ELC.ACCS.ZS?locations=IN', 'B', 'CC BY 4.0 (World Bank open data terms)', 'Share of population with access to electricity. Modelled for years without a survey.', 'India, 32 annual values', 'Republished and sometimes modelled; check the original provider before using a single value in a claim.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('wb-sh-h2o-basw-zs', 'World Bank WDI, original provider: WHO/UNICEF Joint Monitoring Programme (JMP)', 'People using at least basic drinking water services (% of population)', 'https://data.worldbank.org/indicator/SH.H2O.BASW.ZS?locations=IN', 'B', 'CC BY 4.0 (World Bank open data terms)', '''At least basic'' drinking water: an improved source within a 30-minute round trip. Stricter than the NFHS ''improved source''.', 'India, 25 annual values', 'Republished and sometimes modelled; check the original provider before using a single value in a claim.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('wb-sh-sta-bass-zs', 'World Bank WDI, original provider: WHO/UNICEF Joint Monitoring Programme (JMP)', 'People using at least basic sanitation services (% of population)', 'https://data.worldbank.org/indicator/SH.STA.BASS.ZS?locations=IN', 'B', 'CC BY 4.0 (World Bank open data terms)', '''At least basic'' sanitation: an improved facility not shared with other households. JMP estimates are modelled from surveys.', 'India, 25 annual values', 'Republished and sometimes modelled; check the original provider before using a single value in a claim.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('wb-eg-cft-accs-zs', 'World Bank WDI, original provider: World Health Organization (WHO Household Energy Database)', 'Access to clean fuels and technologies for cooking (% of population)', 'https://data.worldbank.org/indicator/EG.CFT.ACCS.ZS?locations=IN', 'B', 'CC BY 4.0 (World Bank open data terms)', 'Share of population (not households) primarily relying on clean fuels and technologies for cooking. Modelled.', 'India, 25 annual values', 'Republished and sometimes modelled; check the original provider before using a single value in a claim.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('wb-fx-own-totl-fe-zs', 'World Bank WDI, original provider: World Bank Global Findex Database', 'Account ownership at a financial institution or with a mobile-money-service provider, female (% of population ages 15+)', 'https://data.worldbank.org/indicator/FX.OWN.TOTL.FE.ZS?locations=IN', 'B', 'CC BY 4.0 (World Bank open data terms)', 'Women age 15+ with an account at a financial institution or mobile money. NFHS covers women 15-49 only.', 'India, 5 annual values', 'Republished and sometimes modelled; check the original provider before using a single value in a claim.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('wb-sp-dyn-le00-in', 'World Bank WDI, original provider: United Nations World Population Prospects (UN DESA)', 'Life expectancy at birth, total (years)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=IN', 'B', 'CC BY 4.0 (World Bank open data terms)', 'UN estimates, revised with each WPP edition; differs from SRS life tables.', 'India, 65 annual values', 'Republished and sometimes modelled; check the original provider before using a single value in a claim.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('wb-sp-dyn-imrt-in', 'World Bank WDI, original provider: UN Inter-agency Group for Child Mortality Estimation (UN IGME)', 'Mortality rate, infant (per 1,000 live births)', 'https://data.worldbank.org/indicator/SP.DYN.IMRT.IN?locations=IN', 'B', 'CC BY 4.0 (World Bank open data terms)', 'Modelled estimates that smooth survey and SRS data; differs from SRS annual rates.', 'India, 65 annual values', 'Republished and sometimes modelled; check the original provider before using a single value in a claim.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('wb-se-adt-litr-zs', 'World Bank WDI, original provider: UNESCO Institute for Statistics', 'Literacy rate, adult total (% of people ages 15 and above)', 'https://data.worldbank.org/indicator/SE.ADT.LITR.ZS?locations=IN', 'B', 'CC BY 4.0 (World Bank open data terms)', 'Adults age 15+, not the census age 7+ base. Sparse years only.', 'India, 14 annual values', 'Republished and sometimes modelled; check the original provider before using a single value in a claim.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('maddison-2023', 'Maddison Project, Groningen Growth and Development Centre (University of Groningen)', 'Maddison Project Database 2023 (Bolt and van Zanden, 2024)', 'https://doi.org/10.34894/INZBF2', 'C', 'CC BY 4.0', 'Historical GDP per capita in 2011 international dollars (PPP), compiled from national accounts and academic reconstructions. India before 1947: Broadberry, Custodis and Gupta (2015) for 1600-1871; Heston (1983) for 1870-1900; Maddison (1985) for 1900-46 (per the file''s Sources sheets).', 'India, 152 values, 1600-2022', 'Long-run estimates carry wide uncertainty before 1950; benchmark years are not annual data. Cite: Bolt, J. and van Zanden, J.L. (2024), Journal of Economic Surveys, doi:10.1111/joes.12618.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('nfhs5-compendium-phase1', 'IIPS / Ministry of Health and Family Welfare (copy hosted by MoHFW National Health Mission)', 'NFHS-5 State Factsheet Compendium, Phase I (22 states/UTs)', 'https://nhm.gov.in/uhc-day/Session%202/NFHS-5%20State%20Factsheet%20Compendium_Phase-I%20(1).pdf', 'A', 'Government of India publication', 'Household survey; fact sheets print NFHS-5 (2019-20) and NFHS-4 (2015-16) side by side.', '22 states/UTs', 'Provisional fact-sheet results; survey estimates with sampling error.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('nfhs5-compendium-phase2', 'IIPS / Ministry of Health and Family Welfare (copy hosted by The DHS Program, ICF)', 'NFHS-5 India and State Factsheet Compendium, Phase II (India + 14 states/UTs)', 'https://dhsprogram.com/pubs/pdf/OF43/NFHS-5_India_and_State_Factsheet_Compendium_Phase-II.pdf', 'A', 'Government of India publication', 'Household survey; fact sheets print NFHS-5 (2020-21; India 2019-21) and NFHS-4 (2015-16) side by side.', 'India and 14 states/UTs', 'Provisional fact-sheet results; survey estimates with sampling error.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hsis-2023-24-t06', 'Reserve Bank of India (Handbook of Statistics on Indian States 2023-24); original source: Office of the Registrar General and Census Commissioner, Ministry of Home Affairs', 'Table 6: State-wise Literacy Rate (per cent), census years 1951-2011', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/6T_091220248DDB438F8E2C497E8FF554B50EB84197.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Persons literacy rate from each decennial Census as compiled by RBI. Values copied exactly from the Excel table; cells printed as ''-'' (not available) skipped. Taken from the 2023-24 edition because the latest (2024-25) edition dropped the literacy table.', '34 states/UTs plus All India; 1951, 1961, 1971, 1981, 1991, 2001, 2011; 215 values', 'Age base changes: 1951-71 rates relate to population aged 5+, 1981-2011 to aged 7+ (break flagged at first 7+ point). 1951 West Bengal relates to total population incl. 0-4; 1951 Chhattisgarh, Madhya Pradesh, Manipur based on sample population. 2001 India and Manipur exclude three Senapati sub-divisions. Andhra Pradesh is undivided (no Telangana row); Jammu & Kashmir includes Ladakh. Table does not state the territorial basis for pre-2001 figures, though it gives separate figures for Chhattisgarh, Jharkhand and Uttarakhand back to 1951. Dadra & Nagar Haveli and Daman & Diu are printed separately and were left out.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hsis-2024-25-t04', 'Reserve Bank of India (Handbook of Statistics on Indian States 2024-25); original source: Sample Registration System Bulletin, Office of the Registrar General and Census Commissioner, Ministry of Home Affairs', 'Table 4: State-wise Infant Mortality Rate (per thousand live births), 2004-2023', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/4T_11122025025F203A250E46CAB963946C776ADBAF.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'SRS infant deaths per 1,000 live births, total, as compiled by RBI. Values copied exactly; ''.'' (not applicable) and ''-'' (not available) skipped. Dadra & Nagar Haveli values marked ''*'' (2020-2023, footnote: include Daman & Diu) mapped to DH with the marker stripped.', '35 states/UTs plus All India; annual 2004-2023; 694 values', 'Andhra Pradesh is undivided up to 2013 (Telangana not applicable); break flagged at 2014. Table gives no note on whether Jammu & Kashmir includes Ladakh after 2019; no Ladakh row. Dadra & Nagar Haveli and Daman & Diu printed separately for 2004-2019 and left out. SRS estimates for small states/UTs are based on small samples and fluctuate year to year.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hsis-2024-25-t07', 'Reserve Bank of India (Handbook of Statistics on Indian States 2024-25); original source: SRS Abridged Life Tables, Office of the Registrar General and Census Commissioner, Ministry of Home Affairs', 'Table 7: State-wise Life Expectancy (years at birth), 1993-97 to 2019-23', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/7T_11122025164B47839F9943F2BC176783B25CB079.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Expectation of life at birth, ''Total'' column (persons), five-year moving periods from SRS abridged life tables. Values copied exactly; ''-'' skipped. Year = end year of the period.', '22 states plus All India; 27 periods 1993-97 to 2019-23; 527 values', 'Only major states are covered (no NE states other than Assam, no UTs other than Delhi). Bihar, Madhya Pradesh and Uttar Pradesh include Jharkhand, Chhattisgarh and Uttarakhand till 2009-13 (break flagged at 2010-14). Andhra Pradesh includes Telangana till 2013-17 (break at 2014-18). Jammu & Kashmir includes Ladakh in all periods. Overlapping five-year periods are not independent observations.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hsis-2024-25-t20', 'Reserve Bank of India (Handbook of Statistics on Indian States 2024-25); original source: National Statistical Office, Ministry of Statistics and Programme Implementation', 'Table 20: Per Capita Net State Domestic Product (Constant Prices, base 2011-12, rupees), 2011-12 to 2024-25', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/20T_111220252B6EE27737FD4931A99C5A448B7CEC68.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Per capita NSDP at constant 2011-12 prices in rupees, by fiscal year, as compiled by RBI from NSO/MoSPI. Values copied exactly; ''-'' skipped. Year = end year of the fiscal year (2011-12 -> 2012).', '33 states/UTs; fiscal years 2011-12 to 2024-25; 453 values', 'No All-India row in this table (India per capita NNI not included here). Jammu & Kashmir includes Ladakh for 2011-12 to 2018-19 and is UT of J&K only from 2019-20 (break flagged). Telangana is listed from 2011-12, so Andhra Pradesh figures are for residual AP throughout. No Ladakh, Lakshadweep or Dadra & Nagar Haveli and Daman & Diu rows. The table does not flag provisional years, but recent state accounts estimates are routinely revised by MoSPI; several states have no 2024-25 (and Gujarat no 2023-24) figure.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
